input.command:
cd /work/workspace/deliverable && node -e "
const fs=require('fs');
const d=JSON.parse(fs.readFileSync('diligence_findings.json','utf8'));
const keys=['issue','where','why_it_matters','deal_impact','fix'];
const en=['consent','price','indemnity','timing','none'];
let ok=true;
d.forEach((f,i)=>{
  const k=Object.keys(f);
  if(k.length!==5||!keys.every(x=>k.includes(x))){ok=false;console.log('finding',i,'BAD KEYS:',k);}
  if(!en.includes(f.deal_impact)){ok=false;console.log('finding',i,'BAD ENUM:',f.deal_impact);}
});
console.log('findings:',d.length,'schema',ok?'OK':'FAIL');
console.log('impacts:',d.map(f=>f.deal_impact).join(','));
"

